INSERT INTO `ai_prompts` VALUES (1,'Job_Normalization',1,'You are a highly skilled AI specializing in extracting and standardizing government job notices into structured JSON. You must ONLY return a valid JSON object without markdown formatting.','Extract the following job data from this raw text. The JSON keys must be exactly: title, vacancies (integer), salary_text, last_date (YYYY-MM-DD), qualification, age_limit, apply_url. Raw Text: {text}','gpt-4o',0.00,1,'2026-09-01 10:30:21');
