--
-- Table structure for table `ai_questions`
--

DROP TABLE IF EXISTS `ai_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ai_questions` (
  `id` char(36) NOT NULL DEFAULT uuid(),
  `role_id` char(36) DEFAULT NULL,
  `category_id` char(36) DEFAULT NULL,
  `difficulty` enum('easy','medium','hard') DEFAULT 'medium',
  `question_text` text NOT NULL,
  `options_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`options_json`)),
  `correct_option` char(1) NOT NULL,
  `marks` int(11) DEFAULT 10,
  `negative_marks` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `role_id` (`role_id`),
  KEY `category_id` (`category_id`),
  CONSTRAINT `ai_questions_ibfk_1` FOREIGN KEY (`role_id`) REFERENCES `ai_roles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ai_questions_ibfk_2` FOREIGN KEY (`category_id`) REFERENCES `ai_question_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

