DROP TABLE IF EXISTS `articles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `articles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `article_uuid` char(36) NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `article_type` enum('Notification_Guide','Eligibility_Guide','Syllabus_Breakdown','Exam_Pattern','Preparation_Strategy','Cutoff_Analysis','Previous_Year_Analysis','Admit_Card_Guide','Answer_Key_Guide','Result_Guide','General_Recruitment_News') NOT NULL DEFAULT 'Notification_Guide',
  `recruitment_id` bigint(20) unsigned DEFAULT NULL,
  `exam_id` bigint(20) unsigned DEFAULT NULL,
  `job_id` bigint(20) unsigned DEFAULT NULL,
  `content` longtext NOT NULL,
  `excerpt` text DEFAULT NULL,
  `focus_keywords` varchar(512) DEFAULT NULL,
  `quality_score` tinyint(3) unsigned DEFAULT 85,
  `fact_check_status` enum('Pending','Verified_100','Requires_Correction','Rejected') DEFAULT 'Verified_100',
  `status` enum('Draft','Review','Approved','Published','Archived') DEFAULT 'Published',
  `view_count` int(10) unsigned DEFAULT 0,
  `reading_time_minutes` tinyint(3) unsigned DEFAULT 5,
  `published_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_article_uuid` (`article_uuid`),
  UNIQUE KEY `idx_article_slug` (`slug`),
  KEY `idx_article_type_status` (`article_type`,`status`),
  KEY `idx_article_recruitment` (`recruitment_id`),
  KEY `idx_article_exam` (`exam_id`)
) ENGINE=InnoDB AUTO_INCREMENT=562 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
