INSERT INTO `exam_syllabus` VALUES (1,1,1,'Reasoning','Analogies & Classification','[\"Semantic Analogy\", \"Symbolic/Number Analogy\", \"Figural Analogy\"]',16.00,'Moderate',1,'2026-09-01 10:42:21'),(2,1,1,'Reasoning','Coding-Decoding & Series','[\"Number Series\", \"Letter Series\", \"Matrix Coding\"]',20.00,'Moderate',1,'2026-09-01 10:42:21'),(3,1,1,'Quantitative Aptitude','Arithmetic & Number Systems','[\"Percentages\", \"Profit & Loss\", \"Ratio & Proportion\", \"Time & Work\", \"SI & CI\"]',35.00,'Moderate',1,'2026-09-01 10:42:21'),(4,1,1,'Quantitative Aptitude','Advanced Mathematics','[\"Algebra\", \"Geometry & Mensuration\", \"Trigonometry\", \"Heights & Distances\"]',40.00,'Moderate',1,'2026-09-01 10:42:21'),(5,1,1,'General Awareness','Static GK & Polity','[\"Indian Constitution\", \"History & Culture\", \"Geography\", \"Economics\"]',30.00,'Moderate',1,'2026-09-01 10:42:21'),(6,1,1,'General Awareness','Current Affairs & Science','[\"National Events\", \"Awards & Honours\", \"General Science\"]',40.00,'Moderate',1,'2026-09-01 10:42:21'),(7,1,1,'English','Grammar & Vocabulary','[\"Spotting Errors\", \"Fill in the Blanks\", \"Synonyms & Antonyms\", \"Idioms & Phrases\"]',50.00,'Moderate',1,'2026-09-01 10:42:21'),(8,1,1,'English','Reading Comprehension','[\"Cloze Test\", \"Passage Comprehension\"]',30.00,'Moderate',1,'2026-09-01 10:42:21'),(9,2,2,'GS Paper 1','Indian Polity & Governance','[\"Constitution\", \"Panchayati Raj\", \"Public Policy\", \"Rights Issues\"]',22.00,'Moderate',1,'2026-09-01 10:42:21'),(10,2,2,'GS Paper 1','Economy & Social Development','[\"Sustainable Development\", \"Poverty\", \"Inclusion\", \"Demographics\"]',20.00,'Moderate',1,'2026-09-01 10:42:21'),(11,2,2,'GS Paper 1','Environment & Ecology','[\"Biodiversity\", \"Climate Change\", \"Environmental Impact\"]',25.00,'Moderate',1,'2026-09-01 10:42:21'),(12,2,2,'GS Paper 1','History of India & National Movement','[\"Ancient & Medieval India\", \"Modern Indian History\", \"Freedom Struggle\"]',18.00,'Moderate',1,'2026-09-01 10:42:21'),(15,4,4,'Quantitative Aptitude','Data Interpretation & Quadratic Equations','[\"Tabular DI\", \"Pie Chart\", \"Bar Graph\", \"Caselet DI\"]',45.00,'Moderate',1,'2026-09-01 10:42:21'),(16,4,4,'Reasoning Ability','Puzzles & Seating Arrangement','[\"Linear Arrangement\", \"Circular Arrangement\", \"Floor Based Puzzles\", \"Box Puzzles\"]',55.00,'Moderate',1,'2026-09-01 10:42:21'),(17,15,10,'Mathematics','Number System, BODMAS & Decimals','[\"Fractions\", \"LCM & HCF\", \"Ratio\", \"Percentage\"]',25.00,'Moderate',1,'2026-09-05 07:19:18'),(18,15,10,'General Awareness','General Science & Current Events','[\"Physics\", \"Chemistry\", \"Life Sciences up to 10th CBSE\", \"Current Affairs\"]',45.00,'Moderate',1,'2026-09-05 07:19:18'),(19,26,21,'Quantitative Aptitude','Advanced Data Interpretation','[\"Radar Graph\", \"Missing DI\", \"Caselets\"]',50.00,'Moderate',1,'2026-09-05 10:50:51'),(20,26,21,'Reasoning Ability','High-Level Puzzles','[\"Uncertain Puzzles\", \"Input-Output\", \"Critical Reasoning\"]',50.00,'Moderate',1,'2026-09-05 10:50:51'),(21,27,22,'Numerical Ability','Simplification & Approximation','[\"BODMAS\", \"Square Roots\", \"Percentages\"]',35.00,'Moderate',1,'2026-09-05 10:50:51'),(22,27,22,'Reasoning Ability','Syllogisms & Inequalities','[\"Only a few Cases\", \"Coded Inequality\"]',30.00,'Moderate',1,'2026-09-05 10:50:51'),(23,28,23,'English','Grammar & Vocab','[\"Spotting Error\", \"Direct Indirect\", \"Active Passive\"]',25.00,'Moderate',1,'2026-09-05 10:50:51'),(24,28,23,'Quant','Basic Arithmetic','[\"Profit Loss\", \"Time Work\", \"Algebra\"]',25.00,'Moderate',1,'2026-09-05 10:50:51'),(25,29,24,'GK','Defence & Current Events','[\"Indian Armed Forces\", \"Modern Warfare\", \"Geography\"]',35.00,'Moderate',1,'2026-09-05 10:50:51'),(26,29,24,'Math','Geometry & Trigonometry','[\"Circles\", \"Triangles\", \"Heights & Distances\"]',35.00,'Moderate',1,'2026-09-05 10:50:51'),(27,30,25,'Math','Calculus & Algebra','[\"Matrices\", \"Differential Calculus\", \"Vectors\"]',40.00,'Moderate',1,'2026-09-05 10:50:51'),(28,30,25,'GAT','English & General Science','[\"Physics\", \"Chemistry\", \"World History\"]',60.00,'Moderate',1,'2026-09-05 10:50:51'),(29,31,26,'Military Aptitude','Spatial & Embedded Figures','[\"Figure Matrix\", \"Pattern Completion\"]',25.00,'Moderate',1,'2026-09-05 10:50:51'),(30,31,26,'General Awareness','Defence & International Affairs','[\"Air Force Commands\", \"Aircraft & Missiles\"]',25.00,'Moderate',1,'2026-09-05 10:50:51'),(31,32,27,'Arithmetic','Percentages & Ratio','[\"Time Distance\", \"Average\", \"Simple Compound Interest\"]',35.00,'Moderate',1,'2026-09-05 10:50:51'),(32,32,27,'General Awareness','Indian Railways & Constitution','[\"Railway Zones\", \"History\", \"Current Affairs\"]',50.00,'Moderate',1,'2026-09-05 10:50:51'),(33,33,28,'GS I','History & Heritage of Gujarat','[\"Solanki Era\", \"Indus Valley in Gujarat\", \"Folklore\"]',30.00,'Moderate',1,'2026-09-05 10:50:51'),(34,33,28,'GS II','Economy of Gujarat & Public Administration','[\"Ports & Logistics\", \"Sardar Sarovar\", \"Panchayati Raj\"]',35.00,'Moderate',1,'2026-09-05 10:50:51'),(35,34,29,'GS I','Uttar Pradesh Special & National History','[\"UP History & Culture\", \"Indian Polity\", \"Geography\"]',30.00,'Moderate',1,'2026-09-05 10:50:51'),(36,34,29,'GS I','Current Affairs & Environment','[\"National Schemes\", \"Ecology\"]',25.00,'Moderate',1,'2026-09-05 10:50:51'),(37,35,30,'GS','Bihar Special & Freedom Movement','[\"Kunwar Singh Role\", \"Ancient Magadha\", \"Modern Bihar\"]',30.00,'Moderate',1,'2026-09-05 10:50:51'),(38,35,30,'GS','General Science & Current Affairs','[\"Physics\", \"Chemistry\", \"Biology\", \"National Events\"]',40.00,'Moderate',1,'2026-09-05 10:50:52');
