INSERT INTO `jobs` VALUES ('0017a1cd-d101-4e1a-991b-fa9ff24dc242','Content Producer - OTT','Develop and produce original digital series and films for Netflix, Amazon Prime, and JioCinema. Manage end-to-end production from script to final delivery, handling budgets of Ôé╣2-10 Cr.','Permanent','12-22 LPA','On-site','4-8 Years',NULL,NULL,NULL,'[\"OTT Content Production\",\"Script Development\",\"Production Planning\",\"Budget Management\",\"Netflix\\/Amazon\"]','OPEN','Mumbai','2026-07-29 10:31:18','2026-07-29 10:31:18','7aeb3a6d-3995-4faa-bab4-4fe2aad700a1','f593c031-1006-4d4d-8cdf-5bf7d9ded0a1','Production','Film / OTT Production','Full Time','{\"min\":\"12\",\"max\":\"22\",\"currency\":\"INR\",\"display\":\"12-22 LPA\"}','{\"min\":\"4\",\"max\":\"8\",\"display\":\"4-8 Years\"}',NULL,'{\"responsibilities\":\"Develop and produce original digital series and films for Netflix, Amazon Prime, and JioCinema. Manage end-to-end production from script to final delivery, handling budgets of \\u20b92-10 Cr.\",\"preferred_profile\":\"Candidate should have strong knowledge of OTT Content Production, Script Development, Production Planning, Budget Management, Netflix\\/Amazon. Good communication skills required.\",\"perks\":\"Medical Insurance, Paid Leaves, Flexible Hours, Learning Budget, Team Outings\"}','{\"openings\":4,\"hiring_urgency\":\"Immediately\",\"walk_in\":false}','{\"apply_mode\":\"Online\",\"contact_email\":\"recruit@creativestudiohub.in\"}','{\"city\":\"Mumbai\",\"country\":\"India\"}',0,NULL),('003dde19-089e-484c-8a6f-722bb5d6a7d8','Real Estate Sales Manager','Drive residential unit sales for our premium township project. Manage a team of 10 sales executives, develop channel partner network, and achieve monthly sales targets of 15+ units.','Permanent','12-22 LPA','On-site','4-7 Years',NULL,NULL,NULL,'[\"Real Estate Sales\",\"CRM\",\"Channel Partners\",\"Negotiation\",\"Property Law\"]','OPEN','Pune','2026-07-29 10:31:18','2026-07-29 10:31:18','f701be4f-05c4-411a-a