--
-- Table structure for table `recruitments`
--

DROP TABLE IF EXISTS `recruitments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `recruitments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `recruitment_uuid` char(36) NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `organization_id` bigint(20) unsigned DEFAULT NULL,
  `organization_name` varchar(255) NOT NULL,
  `advertisement_number` varchar(100) DEFAULT NULL,
  `notification_number` varchar(100) DEFAULT NULL,
  `year` int(10) unsigned NOT NULL DEFAULT 2026,
  `total_vacancies` int(10) unsigned DEFAULT NULL,
  `status` enum('Upcoming','Active','Exam_Phase','Result_Declared','Completed','Cancelled','Archived') NOT NULL DEFAULT 'Active',
  `review_status` enum('VERIFIED','REVIEW_PENDING','REJECTED') NOT NULL DEFAULT 'VERIFIED',
  `anomaly_flags` varchar(500) DEFAULT NULL,
  `primary_notification_url` varchar(1024) DEFAULT NULL,
  `official_website_url` varchar(512) DEFAULT NULL,
  `official_apply_url` varchar(1024) DEFAULT NULL,
  `state_code` varchar(10) DEFAULT 'ALL',
  `qualification_level` varchar(100) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `is_verified` tinyint(1) DEFAULT 1,
  `verified_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_recruitment_uuid` (`recruitment_uuid`),
  UNIQUE KEY `idx_recruitment_slug` (`slug`),
  KEY `idx_recruitment_org` (`organization_name`),
  KEY `idx_recruitment_status` (`status`,`year`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `recruitments`
--

LOCK TABLES `recruitments` WRITE;
