DROP TABLE IF EXISTS `workflow_execution_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `workflow_execution_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `workflow_name` varchar(255) NOT NULL,
  `execution_id` varchar(255) NOT NULL,
  `node_name` varchar(255) NOT NULL,
  `status` enum('Success','Failed','Running','Warning') NOT NULL,
  `execution_time_ms` int(10) unsigned DEFAULT NULL,
  `input_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`input_data`)),
  `output_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`output_data`)),
  `error_message` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_wf_exec` (`workflow_name`,`status`),
  KEY `idx_wf_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

